    rca_fix_fiber_cut: 'Permanent fix: re-route the exposed drop span through protective conduit and move the splice point off the exposed span, sealed inside a joint box.',
    rca_fix_fiber_splice_loss: 'Permanent fix: re-splice with the fusion splicer, verify the RX reading at the customer end, and seal the joint in a proper splice closure box — no hand twists.',
    rca_fix_fiber_cut_splice: 'Permanent fix: re-route the exposed span through protective conduit, fusion-splice the break, and seal the joint in a proper closure box.',
    rca_fix_router_config: 'Permanent fix: save the working router settings on the customer profile, set a fixed IP / PPPoE plan, and replace the router if it keeps losing its configuration.',
    rca_fix_cat6_connector: 'Permanent fix: replace the full CAT6 run with outdoor-grade cable and fresh RJ45 connectors at both ends instead of re-crimping the old ends.',
